package dashboard

// DashboardRouteAuthKind is the authentication boundary enforced before a
// registered Dashboard handler is allowed to run.
type DashboardRouteAuthKind string

const (
	DashboardRouteAuthPublic    DashboardRouteAuthKind = "public"
	DashboardRouteAuthIdentity  DashboardRouteAuthKind = "identity-authenticated"
	DashboardRouteAuthPrincipal DashboardRouteAuthKind = "dashboard-principal"
	DashboardRouteAuthSaaS      DashboardRouteAuthKind = "saas-principal"
)

// DashboardRoute binds routing evidence and authentication policy in one typed
// production registry. The release audit verifies this registry against the
// independently discovered runtime registrations and handler symbols.
type DashboardRoute struct {
	Method   string
	Path     string
	Handler  string
	AuthKind DashboardRouteAuthKind
}

