var dashboardRouteIndex = func() map[string]DashboardRoute {
	index := make(map[string]DashboardRoute, len(dashboardRouteRegistry))
	for _, route := range dashboardRouteRegistry {
		index[route.Method+" "+route.Path] = route
	}
	return index
}()

func DashboardRouteRegistry() []DashboardRoute {
	return append([]DashboardRoute(nil), dashboardRouteRegistry...)
}

func LookupDashboardRoute(method, path string) (DashboardRoute, bool) {
	route, ok := dashboardRouteIndex[method+" "+path]
	return route, ok
}

func contractsByAuthKinds(kinds ...DashboardRouteAuthKind) []string {
	accepted := make(map[DashboardRouteAuthKind]struct{}, len(kinds))
	for _, kind := range kinds {
		accepted[kind] = struct{}{}
	}
	contracts := make([]string, 0)
	for _, route := range dashboardRouteRegistry {
		if _, ok := accepted[route.AuthKind]; ok {
			contracts = append(contracts, route.Method+" "+route.Path)
		}
	}
	return contracts
}

func ExactExemptDashboardRouteContracts() []string {
	return contractsByAuthKinds(DashboardRouteAuthPublic, DashboardRouteAuthIdentity, DashboardRouteAuthSaaS)
}

func PublicDashboardRouteContracts() []string {
	return contractsByAuthKinds(DashboardRouteAuthPublic)
}
